namespace SirketMotoru.Isletim;

public static class SirketYonetimHtml
{
    public const string Icerik = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Şirket Yönetim V9</title>
<style>
:root{color-scheme:dark;--bg:#050914;--p:#0d1728;--p2:#122039;--l:#2b4668;--t:#edf7ff;--m:#91a9c5;--g:#43e0a0;--b:#61a9ff;--r:#ff6d7e;--y:#ffd166;--v:#bd8cff}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 8% 0,#173c68 0,transparent 32%),radial-gradient(circle at 92% 0,#34205e 0,transparent 30%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:10px}.shell{max-width:2200px;margin:auto}.top{position:sticky;top:5px;z-index:20;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 15px;border:1px solid var(--l);border-radius:15px;background:#081321f2}.brand{font-size:19px;font-weight:1000}.brand small{display:block;color:var(--m);font-size:9px}.row,.tabs,.status{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.pill,.tag{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#09172a;color:var(--m);font-size:9px}.hidden{display:none!important}.login{max-width:430px;margin:10vh auto;padding:24px;border:1px solid var(--l);border-radius:18px;background:var(--p)}button,input,select{font:inherit}button{cursor:pointer;border:0;border-radius:8px;padding:8px 11px;background:var(--g);color:#032018;font-weight:900}button.secondary{background:#203754;color:var(--t)}button.danger{background:var(--r);color:#fff}.tabs{margin:10px 0}.tab{background:#0a1628;color:var(--m);border:1px solid var(--l);border-radius:999px}.tab.active{background:linear-gradient(135deg,var(--g),var(--b));color:#03151c}.metrics{display:grid;grid-template-columns:repeat(8,minmax(110px,1fr));gap:8px}.metric,.card,.item{border:1px solid var(--l);border-radius:12px;background:linear-gradient(180deg,var(--p2),#091423)}.metric{padding:10px}.metric span,.sub,label{display:block;color:var(--m);font-size:9px}.metric b{display:block;margin-top:5px;font-size:16px}.card{padding:13px;margin-bottom:10px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.item{padding:10px}.item h3{margin:0 0 5px;font-size:13px}.item p{margin:4px 0;color:var(--m);font-size:9px}.title{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:9px}.title h2{margin:0;font-size:15px}.form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;align-items:end}input,select{width:100%;margin-top:4px;padding:8px;border:1px solid var(--l);border-radius:8px;background:#06111f;color:var(--t)}input[type=range]{padding:0;accent-color:var(--g)}.rangeLine{display:grid;grid-template-columns:220px 1fr 90px;gap:10px;align-items:center;padding:8px;border-bottom:1px solid #1b2d45}.rangeLine output{text-align:right;font-weight:900}.tablewrap{overflow:auto;max-height:680px;scrollbar-gutter:stable}table{width:100%;border-collapse:collapse;min-width:1050px;font-size:9px}th{position:sticky;top:0;background:#101d31;color:var(--m);padding:8px;text-align:left;z-index:2}td{padding:8px;border-bottom:1px solid #1b2b42;vertical-align:top}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.notice{padding:10px;border:1px solid var(--l);border-radius:10px;color:var(--m);margin:8px 0}.fixed{border-color:#39765e;background:#10251d}.bar{height:8px;background:#14243b;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}.ticker{overflow:hidden;white-space:nowrap;border:1px solid #765d2a;background:#21180c;border-radius:10px;margin:9px 0}.ticker div{display:inline-block;padding:9px 0;color:var(--y);font-size:10px;font-weight:800;animation:ticker 240s linear infinite}@keyframes ticker{from{transform:translateX(100vw)}to{transform:translateX(-100%)}}#toast{position:fixed;right:12px;bottom:12px;max-width:520px;z-index:90;background:#10243b}@media(max-width:1500px){.metrics{grid-template-columns:repeat(4,1fr)}.grid3{grid-template-columns:repeat(2,1fr)}}@media(max-width:850px){.top{position:static;flex-direction:column;align-items:flex-start}.metrics,.grid,.grid3,.form{grid-template-columns:1fr}.rangeLine{grid-template-columns:1fr}}
</style></head><body><div class="shell"><header class="top"><div class="brand">ŞİRKET YÖNETİM MERKEZİ V9<small>Tek ekonomi · fiziksel kapasite tahsisi · trendli arz-talep</small></div><div class="status"><span class="pill">Motor <b id="conn">Kontrol</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Panel <b id="panelName">Giriş</b></span><button id="logout" class="secondary hidden">Çıkış</button></div></header>
<section id="loginView" class="login"><h1>Şirket hesabı</h1><p class="sub">V9 temiz sezon yönetimi</p><label>Kullanıcı adı<input id="username" autocomplete="username"></label><label>Parola<input id="password" type="password" autocomplete="current-password"></label><button id="login" style="width:100%;margin-top:10px">Giriş yap</button><div id="loginMsg" class="notice">Motor kontrol ediliyor…</div></section>
<main id="app" class="hidden"><div class="ticker"><div id="ticker">V9 piyasa haberleri hazırlanıyor…</div></div><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"></nav><section id="root"></section></main></div><div id="toast" class="notice hidden"></div>
<script>
'use strict';const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0));
const TABS=[['overview','Genel'],['market','Arz & Talep'],['capacity','Kapasite Tahsisi'],['products','Uygulamalar & OS'],['services','Hizmetler'],['protocols','Protokoller'],['infra','Yatırım'],['finance','Finans'],['account','Hesap']];
const S={d:null,auth:false,active:TABS.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview',timer:null,loading:false,drafts:new Map(),scroll:false,scrollTimer:null};const draft=(k,v)=>S.drafts.has(k)?S.drafts.get(k):v??'';
function toast(t,ok=true){const e=$('#toast');e.textContent=t;e.className=`notice ${ok?'good':'bad'}`;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),5000)}async function req(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let d;try{d=await r.json()}catch{d={basarili:false,aciklama:'Yanıt okunamadı.'}}if(r.status===401){showLogin(d.aciklama||'Oturum bitti.');throw Error('Oturum bitti.')}if(!r.ok||d.basarili===false)throw Error(d.aciklama||`HTTP ${r.status}`);return d}
function showLogin(m='Giriş yapın.'){S.auth=false;clearInterval(S.timer);S.timer=null;$('#app').classList.add('hidden');$('#logout').classList.add('hidden');$('#loginView').classList.remove('hidden');$('#loginMsg').textContent=m;$('#panelName').textContent='Giriş'}function showApp(){S.auth=true;$('#loginView').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');tabs();render()}
async function login(){try{const r=await req('/api/giris',{kullaniciAdi:$('#username').value,parola:$('#password').value});showApp();await refresh(true);S.timer=setInterval(()=>refresh(false),1000);toast(r.aciklama)}catch(e){$('#loginMsg').textContent=e.message}}async function health(){try{const r=await fetch('/api/saglik',{cache:'no-store'});const d=await r.json();$('#conn').textContent=d.durum==='calisiyor'?'Çalışıyor':'Sorun';$('#loginMsg').textContent='Motor hazır.'}catch{$('#conn').textContent='Bağlantı yok'}}
function tabs(){$('#tabs').innerHTML=TABS.map(x=>`<button class="tab ${S.active===x[0]?'active':''}" data-tab="${x[0]}">${x[1]}</button>`).join('');$('#panelName').textContent=TABS.find(x=>x[0]===S.active)?.[1]||S.active}function tab(id){if(!TABS.some(x=>x[0]===id))id='overview';S.active=id;history.replaceState(null,'',`#${id}`);tabs();render()}function editing(){return !!document.activeElement?.matches('input,select,textarea')}
async function refresh(force){if(!S.auth||S.loading||editing()||S.scroll)return;S.loading=true;try{S.d=await req('/api/durum');$('#tick').textContent=S.d.v9?.sonTick||0;render();ticker()}catch(e){if(S.auth)toast(e.message,false)}finally{S.loading=false}}
function metrics(d){const s=d.sirket||{},v=d.v9||{},o=v.sirketOzeti||{},k=v.kapasite||{},i=d.isletim||{};return [['Kasa',money(s.kasa)],['Tick net',money(o.netKazanc)],['Uygulama geliri',money(o.uygulamaGeliri)],['Hizmet geliri',money(o.hizmetGeliri)],['İşletme gideri',money(o.isletmeGideri)],['Aktif borç',money(o.aktifBorc)],['Kapasite',`${int(k.kullanilanKapasite)}/${int(k.toplamFizikselKapasite)}`],['Şirket değeri',money(i.sirketDegeri)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function render(){if(!S.d)return;const y=window.scrollY;$('#metrics').innerHTML=metrics(S.d);$('#root').innerHTML=({overview,market,capacity,products,services,protocols,infra,finance,account}[S.active]||overview)(S.d);requestAnimationFrame(()=>window.scrollTo(0,y))}function ticker(){const h=S.d?.v9?.haberler||[];$('#ticker').textContent=h.map(x=>`✦ ${x.baslik} — ${x.aciklama}`).join('       ')||'V9 piyasası sakin.'}
function overview(d){const s=d.sirket||{},o=d.v9?.sirketOzeti||{},k=d.v9?.kapasite||{},os=d.v9?.isletimSistemiTalebi||{};return `<div class="notice fixed"><b>V9 kuralı:</b> Boşta duran ilanlar borç makinesi değildir. Gider yalnız kullanılan kaynak, düşük taban işletme ve altyapı bakımından oluşur. Otomatik kurtarma kredisi yoktur.</div><div class="grid3"><div class="card"><h2>${esc(s.sirketAdi)}</h2><p>Kalite ${num(s.kodKalitesiPuani)} · Performans ${num(s.performansPuani)} · Güvenlik ${num(s.guvenlikPuani)}</p><p>İtibar ${num(s.itibarPuani)} · Güvenilirlik ${num(s.guvenilirlikPuani)}</p></div><div class="card"><h2>Kapasite</h2><p>Toplam <b>${int(k.toplamFizikselKapasite)}</b></p><p>Ayrılmış ${int(k.ayrilmisKapasite)} · Boş ${int(k.bosKapasite)}</p><p>Kullanılan ${int(k.kullanilanKapasite)} · Doluluk %${num(k.dolulukOrani)}</p></div><div class="card"><h2>Pazar</h2><p>OS talebi ${int(os.buTickTalep)} · karşılanan ${int(os.karsilananTalep)}</p><p>Uygulama kullanıcısı ${int(o.aktifUygulamaKullanicisi)}</p><p>OS kullanıcısı ${int(o.isletimSistemiKullanicisi)}</p></div></div>${market(d)}`}
function market(d){const v=d.v9||{},os=v.isletimSistemiTalebi||{},apps=v.uygulamaTalepleri||[],hs=v.hizmetTalepleri||[];return `<div class="card"><div class="title"><h2>İşletim sistemi arz-talebi</h2><span class="tag">${int(os.karsilananTalep)}/${int(os.buTickTalep)}</span></div>${demandRow(os)}${supply(os)}</div><div class="grid"><div class="card"><h2>Uygulama kategorileri</h2><div class="tablewrap"><table><tr><th>Kategori</th><th>Talep</th><th>Karşılanan</th><th>Arz</th><th>Açık</th><th>Trend</th><th>Oran</th></tr>${apps.map(x=>`<tr><td>${esc(x.ad)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.arzKapasitesi)}</td><td class="${x.karsilanamayanTalep>0?'warn':'good'}">${int(x.karsilanamayanTalep)}</td><td>${trend(x)}</td><td>%${num(x.karsilanmaOrani)}</td></tr>`).join('')}</table></div></div><div class="card"><h2>Hizmet talebi</h2><div class="tablewrap"><table><tr><th>Hizmet</th><th>Talep</th><th>Karşılanan</th><th>Arz</th><th>Açık</th><th>Trend</th></tr>${hs.slice(0,250).map(x=>`<tr><td>${esc(x.ad)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.arzKapasitesi)}</td><td>${int(x.karsilanamayanTalep)}</td><td>${trend(x)}</td></tr>`).join('')}</table></div></div></div>`}function demandRow(x){const p=x.buTickTalep?Math.min(100,x.karsilananTalep*100/x.buTickTalep):0;return `<p>Talep <b>${int(x.buTickTalep)}</b> · karşılanan <b>${int(x.karsilananTalep)}</b> · arz <b>${int(x.arzKapasitesi)}</b> · açık <b class="warn">${int(x.karsilanamayanTalep)}</b></p><div class="bar"><i style="width:${p}%"></i></div>`}function supply(x){return `<div class="grid3" style="margin-top:9px">${(x.arzDagilimi||[]).map(a=>`<div class="item"><h3>${esc(a.ad)}</h3><p>${esc(a.sirketAdi)}</p><p>${int(a.karsilanan)} kullanıcı · %${num(a.pazarPayi)}</p><p>Kapasite ${int(a.kapasite)} · ${money(a.fiyat)}</p></div>`).join('')}</div>`}function trend(x){return `<span class="${Number(x.degisimYuzdesi)>=0?'good':'bad'}">${Number(x.degisimYuzdesi)>=0?'▲':'▼'} %${num(Math.abs(x.degisimYuzdesi))}</span> · ${esc(x.aktifTrend)}`}
function capacity(d){const k=d.v9?.kapasite||{},alloc=k.tahsisler||{},hs=d.kodTabanliYayinlar?.hizmetler||[],ps=d.isletim?.urunler||[];const rows=[...hs.filter(x=>x.aktif).map(x=>({key:`hizmet:${x.hizmetKimligi}@${x.hizmetSurumu}`,name:`Hizmet · ${x.hizmetKimligi}`,use:x.etkinKapasite||0})),...ps.filter(x=>x.aktif).map(x=>({key:`urun:${x.urunKimligi}`,name:`${x.urunTuru} · ${x.urunAdi}`,use:x.aktifKullaniciSayisi||0}))];return `<div class="notice fixed">Toplam fiziksel kapasite: <b>${int(k.toplamFizikselKapasite)}</b>. Sliderların toplamı bu değeri aşamaz. Hizmet veya uygulama kapasitesi ayrıca satın alınmaz.</div><div class="card"><div class="title"><h2>Kapasite tahsisi</h2><span id="capTotal" class="tag">Ayrılan ${int(k.ayrilmisKapasite)} / ${int(k.toplamFizikselKapasite)}</span></div>${rows.map(r=>`<div class="rangeLine"><div><b>${esc(r.name)}</b><span class="sub">Mevcut kullanım ${int(r.use)}</span></div><input type="range" min="0" max="${int(k.toplamFizikselKapasite)}" step="10" value="${Number(draft('cap:'+r.key,alloc[r.key]||0))}" data-cap="${esc(r.key)}"><output data-capout="${esc(r.key)}">${int(draft('cap:'+r.key,alloc[r.key]||0))}</output></div>`).join('')||'<p>Aktif hizmet veya ürün yok.</p>'}<button data-action="capacity-save">Tahsisleri kaydet</button></div>`}
function protoOpts(d){return [['','Protokol seçin'],...(d.protokolKataloguV9||[]).filter(x=>x.aktif&&x.kullanilabilir).map(x=>[x.protokolKimligi,`${x.protokolAdi} — ${x.sahipSirketAdi}`])]}function osOpts(d){return [['','OS seçin'],...(d.ekosistem?.isletimSistemleri||[]).filter(x=>x.aktif).map(x=>[x.uygulamaKimligi,`${x.uygulamaAdi} — ${x.sirketAdi}`])]}function sel(k,v,opts){const x=String(draft(k,v));return `<select data-key="${esc(k)}">${opts.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===x?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`}
function products(d){const apps=d.kodTabanliYayinlar?.uygulamalar||[],urunler=d.isletim?.urunler||[],dag=d.ekosistem?.dagitimAyarlari||[],ranges=d.fiyatAraliklariV9||{};const idx=Object.fromEntries(urunler.map(x=>[x.urunKimligi,x]));return `<div class="notice">Fiyatlar sınırsız değildir. Her kategori kendi min–max sliderına sahiptir. Kullanım yüzdesi gerçek aktif kullanıcı / ayrılmış kapasitedir.</div><div class="grid">${apps.map(a=>{const u=a.uygulama||{},p=idx[a.urunKimligi];if(!p){const r=ranges['manifest:'+u.uygulamaKimligi]||{min:2,max:120,adim:1,onerilen:25},k='new:'+u.uygulamaKimligi;return `<div class="card"><h2>${esc(u.uygulamaAdi)}</h2><p>${esc(u.urunTuru)} · ${esc(u.kategori)}</p><label>Başlangıç fiyatı <b data-priceout="${esc(k)}">${money(draft(k+':price',r.onerilen))}</b><input type="range" min="${r.min}" max="${r.max}" step="${r.adim}" value="${draft(k+':price',r.onerilen)}" data-price="${esc(k)}"></label><div class="form">${u.urunTuru==='isletim-sistemi'?'':`<label>İşletim sistemi${sel(k+':os','',osOpts(d))}</label>`}<label>Protokol${sel(k+':proto','',protoOpts(d))}</label><label>Model${sel(k+':model','abonelik',[['abonelik','Abonelik'],['kullanim','Kullanım'],['freemium','Freemium'],['lisans','Lisans']])}</label></div><button data-action="publish" data-id="${esc(u.uygulamaKimligi)}" data-type="${esc(u.urunTuru)}">Yayına al</button></div>`}const r=ranges[p.urunKimligi]||{min:2,max:120,adim:1},k='prod:'+p.urunKimligi,price=p.fiyatlandirmaModeli==='kullanim'?p.kullanimBasinaUcret:p.abonelikUcreti,da=(dag.find(x=>x.urunKimligi===p.urunKimligi)||{}).ayar||{},pct=p.kullaniciKapasitesi?Math.min(999,p.aktifKullaniciSayisi*100/p.kullaniciKapasitesi):0;return `<div class="card"><div class="title"><h2>${esc(p.urunAdi)}</h2><span class="tag ${p.aktif?'good':'bad'}">${p.aktif?'AKTİF':'PASİF'}</span></div><p>${esc(p.urunTuru)} · ${esc(p.kategori)} · ${esc(p.fiyatlandirmaModeli)}</p><p>Kullanıcı <b>${int(p.aktifKullaniciSayisi)}</b> / ${int(p.kullaniciKapasitesi)} · <b>%${num(pct)}</b></p><div class="bar"><i style="width:${Math.min(100,pct)}%"></i></div><label>Fiyat <b data-priceout="${esc(k)}">${money(draft(k+':price',price))}</b><input type="range" min="${r.min}" max="${r.max}" step="${r.adim}" value="${draft(k+':price',price)}" data-price="${esc(k)}"></label><div class="form">${p.urunTuru==='isletim-sistemi'?'':`<label>OS${sel(k+':os',da.isletimSistemiKimligi||'',osOpts(d))}</label>`}<label>Protokol${sel(k+':proto',da.baglantiProtokoluKimligi||'',protoOpts(d))}</label><label>Durum${sel(k+':active',String(p.aktif),[['true','Aktif'],['false','Pasif']])}</label></div><div class="row"><button data-action="price-save" data-id="${esc(p.urunKimligi)}" data-model="${esc(p.fiyatlandirmaModeli)}">Fiyatı kaydet</button><button data-action="distribution" data-id="${esc(p.urunKimligi)}" data-type="${esc(p.urunTuru)}">Dağıtımı kaydet</button></div><p class="${da.uyumlu?'good':'warn'}">${esc(da.uyumDurumu||'Dağıtım bekliyor')}</p></div>`}).join('')}</div>`}
function services(d){const hs=d.kodTabanliYayinlar?.hizmetler||[];return `<div class="notice fixed">Hizmet fiyatı ve kapasite satın alımı kapalıdır. Kapasite yalnız tahsis panelinden gelir.</div><div class="tablewrap card"><table><tr><th>Hizmet</th><th>Sabit fiyat</th><th>Tahsis sonrası eşzamanlı</th><th>Durum</th><th>İşlem</th></tr>${hs.map(h=>`<tr><td>${esc(h.hizmetKimligi)}@${esc(h.hizmetSurumu)}</td><td>${money(h.birimFiyat)}</td><td>${int(h.etkinKapasite)}</td><td>${h.aktif?'Aktif':'Pasif'}</td><td><button data-action="service-toggle" data-id="${esc(h.hizmetKimligi)}" data-version="${esc(h.hizmetSurumu)}" data-active="${h.aktif}">${h.aktif?'Durdur':'Aç'}</button></td></tr>`).join('')}</table></div>`}
function protocols(d){return `<div class="notice fixed">Tek protokol kimliği vardır; “kendi” ve “piyasa” kopyası ayrı seçenek değildir.</div><div class="grid3">${(d.protokolKataloguV9||[]).map(p=>`<div class="item"><h3>${esc(p.protokolAdi)}</h3><p>${esc(p.protokolKimligi)} · ${esc(p.sahipSirketAdi)}</p><p>${p.aktif?'Piyasada':'Yayınlanmadı'} · ${esc(p.lisansModeli)}</p>${!p.sahibi&&!p.benimsendi&&p.piyasaKaydiKimligi?`<button data-action="adopt" data-id="${esc(p.piyasaKaydiKimligi)}">Benimse</button>`:''}</div>`).join('')}</div>`}
function infra(d){return `<div class="grid3">${(d.yatirimMagazasi||[]).map(y=>`<div class="item"><h3>${esc(y.ad)} · Lv ${int(y.seviye)}</h3><p>${esc(y.aciklama)}</p><p>Maliyet ${money(y.sonrakiMaliyet)} · kapasite +${int(y.kapasiteKatkisi)}</p><button data-action="invest" data-id="${esc(y.yatirimTuru)}">Yükselt</button></div>`).join('')}</div>`}
function finance(d){const o=d.v9?.sirketOzeti||{},i=d.isletim||{};return `<div class="grid"><div class="card"><h2>V9 bilanço</h2><p>Hizmet geliri ${money(o.hizmetGeliri)}</p><p>Uygulama geliri ${money(o.uygulamaGeliri)}</p><p>Abonelik geliri ${money(o.abonelikGeliri)}</p><p>Protokol geliri ${money(o.protokolGeliri)}</p><p>İşletme gideri ${money(o.isletmeGideri)}</p><p>Finansman gideri ${money(o.finansmanGideri)}</p><p>Net <b class="${Number(o.netKazanc)>=0?'good':'bad'}">${money(o.netKazanc)}</b></p><p>Ödenemeyen gider ${money(i.odenemeyenGider)} <span class="sub">50.000 TL tavanlı, otomatik kredi açmaz</span></p></div><div class="card"><h2>İsteğe bağlı kredi</h2>${(d.krediPaketleri||[]).map(k=>`<div class="item"><h3>${esc(k.ad)}</h3><p>${money(k.asgariTutar)}–${money(k.azamiTutar)} · tick faiz %${num(k.tickFaizOrani*100)}</p><input data-key="loan:${esc(k.krediTuru)}" type="number" value="${draft('loan:'+k.krediTuru,k.asgariTutar)}"><button data-action="loan" data-id="${esc(k.krediTuru)}">Kredi çek</button></div>`).join('')}</div></div>`}
function account(){return `<div class="card"><h2>Parola değiştir</h2><div class="form"><label>Mevcut<input data-key="account:old" type="password"></label><label>Yeni<input data-key="account:new" type="password"></label><button data-action="password">Değiştir</button></div></div>`}
async function action(b){const a=b.dataset.action,id=b.dataset.id;try{b.disabled=true;if(a==='capacity-save'){const tahsisler={};document.querySelectorAll('[data-cap]').forEach(x=>tahsisler[x.dataset.cap]=Number(x.value));await req('/api/kapasite/tahsis',{tahsisler})}else if(a==='publish'){const k='new:'+id,model=String(draft(k+':model','abonelik')),price=Number(draft(k+':price',25));await req('/api/uygulama/yayinla',{uygulamaKimligi:id,fiyatlandirmaModeli:model,abonelikUcreti:model==='kullanim'?0:price,kullanimBasinaUcret:model==='kullanim'?price:0,isletimSistemiKimligi:b.dataset.type==='isletim-sistemi'?'':String(draft(k+':os','')),baglantiProtokoluKimligi:String(draft(k+':proto','')),aktifOlmasiIsteniyor:true})}else if(a==='price-save'){const k='prod:'+id,model=b.dataset.model,price=Number(draft(k+':price',0));await req('/api/uygulama/guncelle',{urunKimligi:id,abonelikUcreti:model==='kullanim'?0:price,kullanimBasinaUcret:model==='kullanim'?price:0,aktif:String(draft(k+':active','true'))==='true'})}else if(a==='distribution'){const k='prod:'+id;await req('/api/uygulama/dagitim',{urunKimligi:id,isletimSistemiKimligi:b.dataset.type==='isletim-sistemi'?'':String(draft(k+':os','')),baglantiProtokoluKimligi:String(draft(k+':proto','')),aktif:String(draft(k+':active','true'))==='true'})}else if(a==='service-toggle')await req('/api/hizmet/durum',{hizmetKimligi:id,hizmetSurumu:b.dataset.version,aktif:b.dataset.active!=='true'});else if(a==='adopt')await req('/api/protokol/benimse',{protokolKimligi:id});else if(a==='invest')await req('/api/yatirim',{yatirimTuru:id});else if(a==='loan')await req('/api/kredi',{krediTuru:id,tutar:Number(draft('loan:'+id,0))});else if(a==='password')await req('/api/parola',{eskiParola:String(draft('account:old','')),yeniParola:String(draft('account:new',''))});S.drafts.clear();await refresh(true);toast('İşlem tamamlandı.')}catch(e){toast(e.message,false)}finally{b.disabled=false}}
$('#login').onclick=login;$('#password').addEventListener('keydown',e=>{if(e.key==='Enter')login()});$('#logout').onclick=async()=>{try{await req('/api/cikis',{})}catch{}showLogin('Çıkış yapıldı.')};$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)tab(b.dataset.tab)});$('#root').addEventListener('input',e=>{const x=e.target.closest('[data-key]');if(x)S.drafts.set(x.dataset.key,x.value);const c=e.target.closest('[data-cap]');if(c){S.drafts.set('cap:'+c.dataset.cap,c.value);document.querySelector(`[data-capout="${CSS.escape(c.dataset.cap)}"]`).textContent=int(c.value);let t=0;document.querySelectorAll('[data-cap]').forEach(z=>t+=Number(z.value));const k=S.d?.v9?.kapasite?.toplamFizikselKapasite||0;$('#capTotal').textContent=`Ayrılan ${int(t)} / ${int(k)}`;$('#capTotal').className=`tag ${t>k?'bad':'good'}`}const p=e.target.closest('[data-price]');if(p){S.drafts.set(p.dataset.price+':price',p.value);document.querySelector(`[data-priceout="${CSS.escape(p.dataset.price)}"]`).textContent=money(p.value)}});$('#root').addEventListener('change',e=>{const x=e.target.closest('[data-key]');if(x)S.drafts.set(x.dataset.key,x.value)});$('#root').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)action(b)});window.addEventListener('scroll',()=>{S.scroll=true;clearTimeout(S.scrollTimer);S.scrollTimer=setTimeout(()=>{S.scroll=false;refresh(false)},300)},{passive:true});window.addEventListener('hashchange',()=>tab(location.hash.slice(1)));showLogin();health();
</script></body></html>
""";
}
